// Regression tests for number-to-string conversion (`bf_ftoa`). Expected
// strings were produced by C libbf.
use libbeef::ftoa::{FormatStyle, ToStringOptions};
use libbeef::{BigFloat, Rounding, Sign};

fn rnd(r: u8) -> Rounding {
    match r {
        0 => Rounding::NearestEven,
        1 => Rounding::TowardZero,
        2 => Rounding::TowardNegative,
        3 => Rounding::TowardPositive,
        4 => Rounding::NearestAway,
        5 => Rounding::AwayFromZero,
        _ => Rounding::Faithful,
    }
}

fn make(kind: &str, sign: u8, expn: i64, hex: &str) -> BigFloat {
    let sign = Sign::from_negative(sign == 1);
    match kind {
        "N" => BigFloat::nan(),
        "I" => BigFloat::infinity(sign),
        "Z" => BigFloat::zero(sign),
        _ => {
            let nl = hex.len() / 16;
            let mut limbs = vec![0u64; nl];
            for i in 0..nl {
                limbs[nl - 1 - i] = u64::from_str_radix(&hex[i * 16..i * 16 + 16], 16).unwrap();
            }
            BigFloat::from_raw(sign, expn, limbs)
        }
    }
}

/// (radix, precision, rounding, libbf flags, kind, sign, raw exp, limbs, expected)
type Case = (
    u8,
    u64,
    u8,
    u32,
    &'static str,
    u8,
    i64,
    &'static str,
    &'static str,
);

fn options(radix: u8, prec: u64, r: u8, flags: u32) -> ToStringOptions {
    ToStringOptions {
        radix,
        precision: prec,
        rounding: rnd(r),
        style: match (flags >> 16) & 3 {
            0 => FormatStyle::Fixed,
            1 => FormatStyle::Fractional,
            2 => FormatStyle::Free,
            _ => FormatStyle::FreeMin,
        },
        force_exponent: flags & 0x10_0000 != 0,
        add_prefix: flags & 0x20_0000 != 0,
        js_quirks: flags & 0x40_0000 != 0,
    }
}

fn check(cases: &[Case]) {
    for &(radix, prec, r, flags, kind, sign, expn, hex, expected) in cases {
        let a = make(kind, sign, expn, hex);
        let s = a.to_string_with(options(radix, prec, r, flags)).unwrap();
        assert_eq!(
            s, expected,
            "radix={radix} prec={prec} rnd={r} flags={flags:#x} {kind} {sign} {expn} {hex}"
        );
    }
}

