#[test]
fn fixed_power_of_two_matches_libbf() {
    check(FIXED_POW2);
}

/// The fixed format switches to exponential notation as soon as the exponent
/// exceeds the number of digits.
#[test]
fn fixed_general_matches_libbf() {
    check(FIXED_GENERAL);
}

#[test]
fn all_formats_match_libbf() {
    check(ALL_FORMATS);
}

#[test]
fn to_string_radix_is_the_fixed_format() {
    let a = make("V", 0, 14, "c0e4000000000000");
    assert_eq!(
        a.to_string_radix(10, 3, Rounding::NearestEven, false)
            .unwrap(),
        "1.23e4"
    );
    assert_eq!(
        a.to_string_radix(10, 8, Rounding::NearestEven, false)
            .unwrap(),
        "12345.000"
    );
    assert_eq!(a.to_string_radix(37, 3, Rounding::NearestEven, false), None);
}
